#define R iResolution.xy
#define T iTime
#define I iFrame
#define Main void mainImage(out vec4 Q, in vec2 U)
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define D(U) texture(iChannel3,(U)/R)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec4 hash(vec4 p) {
                const vec4 k = vec4(0.1031, 0.11369, 0.13787, 0.16379); 
                p = fract(p * k);                                       
                p += dot(p, p.wxyz + k);                                
                p = fract((p.xxyz + p.yzww) * p.zyxw);                  
                return fract(sin(p) * 43758.5453);                      
            }
float ln (vec3 u, vec3 a, vec3 b) {
    return length(u-a-(b-a)*clamp(dot(u-a,b-a)/dot(b-a,b-a),0.,1.));
}

#define M 100.
#define SCALE .5

        #define K1 .0055*SCALE
        #define K2 .2

            float scene (vec3 u) {
                u = 2.*(u-.5*vec3(R,0))/R.y;
                u.y +=.3;
                float o = .25-.25*sign(length(u)-1.5);
                o += .05-.05*sign(abs(length(u)-1.3)-.05*(.5+.5*sign(sin(20.*atan(u.y,u.x)))));
                float d = 1e9;
                for (float i = 0.; i < 10.; i++) {
                   d = min(d,ln(u,vec3(0),vec3(0,-.4*exp2(-.5*(i-1.)),0))-.1*exp2(-.35*i));
                    u.xz = abs(u.xz);
                    u.xy *= ei(-.8*exp2(-.15*i));
                    u.y -= .35*exp2(-.5*i);
                }
                o -= .2-.2*sign(d);
                return .2+2.*o;
            }
Main {

   Q = A(U);
   vec3 p = vec3(U,0);
    Q.z = scene(p);
   vec3 p0 = p;
   vec3 v = vec3(0);
    if (I < 1) {
        Q = vec4(0);
        Q.y = 1.;
        vec3 d = normalize(vec3(3.,.5,0)*vec3(R,0)-vec3(U,0));
        for (float i = U.x; i < R.x; i++) {
            Q.y *= 1.-scene(p)*K1;
            p += d;
        }
    }
    else {
    float s0 = scene(p);
        for (float i = 0.; i < 20.; i++) {
            if (p.x>R.x||p.y>R.y-1.||p.y<0.) break;
            float s = scene(p);
            vec4 q = A(vec2(max(p.x,0.),U.y));
            Q.x += s*q.y*exp(-4.5*length(v-vec3(1,0,0)));
            p += 4.*M/SCALE*v*inversesqrt(1.+M*M*dot(v,v));
            v += s*K2*(hash(vec4(1,1,i,iFrame)).xyz*2.-1.);
        }
    }
    //Q = A(U)+scene(p0);
}
